command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERBANN (Die robusten Wurzeln)
// ==========================================

(async () => {
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined" || !DSK_FW.Zone) return ui.notifications.error("Framework fehlt!");

    const gabenName = "Geisterbann";
    const ahne = "Zerzal";
    const finalEffektName = `${gabenName} (${ahne})`; 
    const zielEffektName = `Zone - Geisterbann - Furcht`; 
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde) DSK_FW.EffektEnde.Register("zerzalGeisterbann", finalEffektName, "Die Skratglyphen verblassen, und die Bannzone löst sich auf.");

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
    let safeTestData = typeof testData !== "undefined" ? testData : null;
    let safeActor = typeof actor !== "undefined" ? actor : null;
    let casterActor = safeTestData?.actor || (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) || safeActor;
    if (!casterActor) casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Kein Wirkender gefunden!");

    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));
    const qsWert = Number(safeTestData?.result?.QL || safeTestData?.qualityStep || casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    if (qsWert <= 0) {
        return ChatMessage.create({ whisper: whisperTargets, speaker: { alias: "System" }, content: `${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}<div class="dskbox2"><p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p></div>` });
    }

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Kein Token des Wirkenden gefunden!");

    const einstellungen = await foundry.applications.api.DialogV2.wait({
        window: { title: "Bannkegel konfigurieren" }, position: { width: 420 },
        content: `
            <form><div style="font-family: 'Signika', sans-serif;">${DSK_FW.UI.Header(finalEffektName, iconBild)}<div class="dskbox2" style="margin-top:10px;">
            <p style="font-size:0.95em; line-height:1.35; margin-bottom: 10px;">Lege die Maße für den magischen Bannkegel fest (max. 12 Schritt):</p>
            <div style="margin-bottom: 8px;"><label style="font-weight: bold; font-size: 0.9em;">Länge (max. 12 Schritt):</label><input type="number" name="laenge" value="12" min="1" max="12" style="width: 100%; padding: 4px; margin-top: 4px;"></div>
            <div><label style="font-weight: bold; font-size: 0.9em;">Öffnungswinkel (max. 170°):</label><input type="number" name="winkel" value="60" min="10" max="170" style="width: 100%; padding: 4px; margin-top: 4px;"></div>
            </div></div></form>`,
        buttons: [{ action: "ok", label: "Weiter", icon: "fas fa-arrow-right", default: true, callback: (event) => { const data = new FormData(event.target.closest("form")); return { laenge: Math.min(12, Math.max(1, Number(data.get("laenge")) || 12)), winkel: Math.min(170, Math.max(10, Number(data.get("winkel")) || 60)) }; } }, { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => null }], rejectClose: false
    });

    if (!einstellungen) return ui.notifications.warn("Bann abgebrochen.");
    const radiusSchritt = einstellungen.laenge; const kegelWinkel = einstellungen.winkel;

    const confirmPosition = async () => {
        return await foundry.applications.api.DialogV2.wait({
            window: { title: "Bannkegel platzieren" }, position: { width: 420 },
            content: `<form><div style="font-family: 'Signika', sans-serif;">${DSK_FW.UI.Header(finalEffektName, iconBild)}<div class="dskbox2" style="margin-top:10px;"><p style="font-size:0.95em; line-height:1.35;">Verschiebe und drehe den Bannkegel (${radiusSchritt} Schritt, ${kegelWinkel}°) auf der Karte.<br><br>Klicke danach auf <b>Position Bestätigen</b>.</p></div></div></form>`,
            buttons: [{ action: "ok", label: "Position Bestätigen", icon: "fas fa-check", default: true, callback: () => true }, { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }], rejectClose: false
        });
    };

    ui.notifications.info("Platziere und richte den Bannkegel aus.");
    const templateData = { t: "cone", user: game.user.id, distance: radiusSchritt, direction: 0, angle: kegelWinkel, x: casterToken.center.x, y: casterToken.center.y, fillColor: game.user.color || "#000000", fillAlpha: 0.15, lineThickness: 1, hidden: false, flags: { dsk: { isZoneSource: true } } };
    const createdTemplates = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [templateData]);
    let templateDoc = createdTemplates[0];

    try { canvas.templates.activate(); } catch (e) {}
    const isConfirmed = await confirmPosition();
    try { canvas.tokens.activate(); } catch (e) {}
    if (!isConfirmed || isConfirmed === false) { await templateDoc.delete(); return ui.notifications.warn("Bann abgebrochen."); }
    let template = canvas.scene.templates.get(templateDoc.id);

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");
    await template.setFlag("dsk", "isZoneSource", true);

    const dauerStunden = qsWert; const erschwernisWillenskraft = qsWert * 3;
    const dauerText = `${dauerStunden} Stunde${dauerStunden > 1 ? 'n' : ''} <span style="font-weight: 300; font-size: 0.9em; opacity: 0.8;">(${qsWert} QS)</span>`;

    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    const successContent = `<div style="font-family: 'Signika', sans-serif;">${DSK_FW.UI.Header(finalEffektName, iconBild)}<div class="dskbox2" style="margin-top:10px;"><p><b>${DSK_FW.ResolveTokenName(casterActor)}</b> formt einen magischen Bannkegel (${radiusSchritt} Schritt, ${kegelWinkel}°) aus Skratglyphen.</p><p style="margin: 8px 0; font-size: 0.9em;"><b>Information:</b><br>Kegel-Zone bindet Geister. Wahrnehmung aktualisiert sich live (Siehe Flüsternachricht).</p><hr><p style="text-align:center; font-weight:bold;">Wirkungsdauer: ${dauerText}</p></div></div>`;
    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) await msg.update({ content: successContent, whisper: whisperTargets });
    else await ChatMessage.create({ whisper: whisperTargets, content: successContent, speaker: { alias: "System" } });
    const radarData = await ChatMessage.create({ content: "Lade Scanner...", whisper: whisperTargets, speaker: { alias: "System" } });

    const trackerConfig = {
        casterActorId: casterActor.id, casterUuid: casterActor.uuid, templateId: template.id, templateUuid: template.uuid, msgId: radarData.id,
        casterEffektName: finalEffektName, zielEffektName: zielEffektName, targetType: "geist", ahne: ahne, radarTitel: `${gabenName} (Radar)`,
        radarInfoText: `<b>Zonen-Effekte (Kegel ${radiusSchritt} Schritt, ${kegelWinkel}°):</b><br>• <b>8 Stufen Status Furcht</b><br>• Willenskraft um <b>${erschwernisWillenskraft} FW</b> <span style="font-weight: 300; font-size: 0.9em; opacity: 0.8;">(${qsWert} QS x 3)</span> erschwert.<br>`,
        dauerText: dauerText,

        effektData: {
            img: iconBild,
            duration: { hours: dauerStunden },
            changes: [
                { key: "system.skillModifiers.FW", mode: 0, value: `Willenskraft -${erschwernisWillenskraft}`, priority: 20 },
                { key: "system.status.feared", mode: 2, value: "8", priority: 20 }
            ],
            statuses: ["feared"],
            description: `Erleidet Furcht und -${erschwernisWillenskraft} FW auf Willenskraft im Bannkegel.`
        }
    };

    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName, icon: iconBild, img: iconBild, duration: { hours: dauerStunden },
        description: `Bannkegel (${radiusSchritt} Schritt, ${kegelWinkel}°) erschaffen.<br>• Geister im Kegel erleiden 8 Stufen Furcht.<br>• Willenskraft um ${erschwernisWillenskraft} FW erschwert.`,
        flags: { dsk: { isZoneSource: true, templateId: template.id, messageId: radarData.id, zielEffektName: zielEffektName, casterEffektName: finalEffektName, radarTitel: `${gabenName} (Radar)`, ahne: ahne, trackerConfig: trackerConfig } }
    }]);

    if (typeof DSK_FW.Zone.StartLiveTracker === "function") DSK_FW.Zone.StartLiveTracker(trackerConfig);
})();
